    private void ConfigureHtmlEditorTab()
    {
        // GUMPEDITOR_HTML_TAB_LAYOUT_V95

        if (_gumpHtmlTab == null)
            return;

        var htmlContainer = new Panel
        {
            Dock = DockStyle.Fill,
            AutoScroll = true,
            Padding = new Padding(4)
        };

        _gumpHtmlTab.Controls.Clear();

        _gumpHtmlTab.Controls.Add(
            htmlContainer);

        if (_gumpHtmlGroup != null)
        {
            _gumpHtmlGroup.Dock =
                DockStyle.Top;

            _gumpHtmlGroup.Height =
                210;

            htmlContainer.Controls.Add(
                _gumpHtmlGroup);
        }

        if (_gumpTextEditorPanel != null)
        {
            _gumpTextEditorPanel.Dock =
                DockStyle.Top;

            _gumpTextEditorPanel.Height =
                250;

            htmlContainer.Controls.Add(
                _gumpTextEditorPanel);
        }
    }

        private void InitializeTextEditor()
{
    if (_propertiesPanel == null)
        return;

    _textEditorGroup =
        new GroupBox
        {
            Text = "Editor de Texto / HTML do Ultima Online",
            Dock = DockStyle.Bottom,
            Height = 450,
            Padding = new Padding(6)
        };

    var top =
        new TableLayoutPanel
        {
            Dock = DockStyle.Top,
            Height = 150,
            ColumnCount = 2,
            RowCount = 4,
            Padding = new Padding(2)
        };

    top.ColumnStyles.Add(
        new ColumnStyle(
            SizeType.Absolute,
            105));

    top.ColumnStyles.Add(
        new ColumnStyle(
            SizeType.Percent,
            100));

    top.RowStyles.Add(
        new RowStyle(
            SizeType.Absolute,
            34));

    top.RowStyles.Add(
        new RowStyle(
            SizeType.Absolute,
            34));

    top.RowStyles.Add(
        new RowStyle(
            SizeType.Absolute,
            34));

    top.RowStyles.Add(
        new RowStyle(
            SizeType.Absolute,
            40));

    // ==============================
    // FONTE UO
    // ==============================

    top.Controls.Add(
        new Label
        {
            Text = "Fonte UO:",
            Dock = DockStyle.Fill,
            TextAlign = ContentAlignment.MiddleLeft
        },
        0,
        0);

    _textFontCombo =
        new ComboBox
        {
            Dock = DockStyle.Fill,
            DropDownStyle =
                ComboBoxStyle.DropDownList,
            DrawMode =
                DrawMode.OwnerDrawFixed,
            ItemHeight = 30,
            DropDownHeight = 420
        };

    if (_uoFontReader != null)
    {
        for (int i = 0;
             i < _uoFontReader.Fonts.Count;
             i++)
        {
            _textFontCombo.Items.Add(
                "Font " + i
            );
        }
    }

    _textFontCombo.SelectedIndex = 0;

    _textFontCombo.DrawItem +=
        TextFontComboDrawItem;

    _textFontCombo.SelectedIndexChanged +=
        TextFontComboChanged;

    top.Controls.Add(
        _textFontCombo,
        1,
        0);

    // ==============================
    // TAMANHO
    // ==============================

    top.Controls.Add(
        new Label
        {
            Text = "Tamanho:",
            Dock = DockStyle.Fill,
            TextAlign = ContentAlignment.MiddleLeft
        },
        0,
        1);

    _textSizeCombo =
        new ComboBox
        {
            Dock = DockStyle.Fill,
            DropDownStyle =
                ComboBoxStyle.DropDownList
        };

    _textSizeCombo.Items.AddRange(
        new object[]
        {
            "Pequeno",
            "Normal",
            "Grande",
            "Muito grande"
        });

    _textSizeCombo.SelectedIndex = 1;

    _textSizeCombo.SelectedIndexChanged +=
        TextFormattingChanged;

    top.Controls.Add(
        _textSizeCombo,
        1,
        1);

    // ==============================
    // ALINHAMENTO
    // ==============================

    top.Controls.Add(
        new Label
        {
            Text = "Alinhamento:",
            Dock = DockStyle.Fill,
            TextAlign = ContentAlignment.MiddleLeft
        },
        0,
        2);

    _textAlignCombo =
        new ComboBox
        {
            Dock = DockStyle.Fill,
            DropDownStyle =
                ComboBoxStyle.DropDownList
        };

    _textAlignCombo.Items.AddRange(
        new object[]
        {
            "Esquerda",
            "Centralizado",
            "Direita",
            "Justificado"
        });

    _textAlignCombo.SelectedIndex = 0;

    _textAlignCombo.SelectedIndexChanged +=
        TextFormattingChanged;

    top.Controls.Add(
        _textAlignCombo,
        1,
