        private void ApplyLightTheme()
        {
            BackColor =
                Color.Gainsboro;

            ForeColor =
                SystemColors.ControlText;

            ApplyLightThemeToControl(
                this);

            if (_menuStrip != null)
            {
                _menuStrip.BackColor =
                    Color.Gainsboro;

                _menuStrip.ForeColor =
                    SystemColors.ControlText;
            }

            if (_toolStrip != null)
            {
                _toolStrip.BackColor =
                    Color.Gainsboro;

                _toolStrip.ForeColor =
                    SystemColors.ControlText;
            }

            if (_statusStrip != null)
            {
                _statusStrip.BackColor =
                    Color.Gainsboro;

                _statusStrip.ForeColor =
                    SystemColors.ControlText;
            }
        }

        private void ApplyLightThemeToControl(
            Control control)
        {
            if (control == null)
                return;

            if (control is MenuStrip ||
                control is ToolStrip ||
                control is StatusStrip)
            {
                control.BackColor =
                    Color.Gainsboro;

                control.ForeColor =
                    SystemColors.ControlText;
            }
            else if (control is TextBox ||
                     control is RichTextBox ||
                     control is ComboBox ||
                     control is NumericUpDown ||
                     control is ListBox)
            {
                control.BackColor =
                    Color.White;

                control.ForeColor =
                    SystemColors.ControlText;
            }
            else if (control is Button)
            {
                control.BackColor =
                    SystemColors.Control;

                control.ForeColor =
                    SystemColors.ControlText;
            }
            else if (control is TabPage ||
                     control is GroupBox ||
                     control is Panel ||
                     control is TableLayoutPanel)
            {
                control.BackColor =
                    Color.Gainsboro;

                control.ForeColor =
                    SystemColors.ControlText;
            }
            else if (control is Label)
            {
                control.BackColor =
                    Color.Transparent;

                control.ForeColor =
                    SystemColors.ControlText;
            }

            foreach (Control child in
                     control.Controls)
            {
                ApplyLightThemeToControl(
                    child);
            }
        }

private Button CreateTextButton(
    string text,
    string tooltip)
{
    var button =
        new Button
        {
            Text = text,
            Width = 38,
            Height = 28,
            FlatStyle =
                FlatStyle.Standard
        };

    var tip =
        new ToolTip();

    tip.SetToolTip(
        button,
        tooltip);

    return button;
}

private void TextFontComboDrawItem(
    object sender,
    DrawItemEventArgs e)
{
    if (e.Index < 0)
        return;

    e.DrawBackground();

    string label =
        "Font " + e.Index;

    if (_uoFontReader != null)
    {
        Bitmap preview =
            _uoFontReader.RenderText(
                e.Index,
                "AaBbCc 0123456789",
                Color.White,
                1.0f);

        if (preview != null)
        {
            Rectangle rect =
                new Rectangle(
                    e.Bounds.X + 4,
                    e.Bounds.Y + 2,
                    Math.Min(
                        preview.Width,
                        190),
                    Math.Min(
                        preview.Height,
                        e.Bounds.Height - 4));

            e.Graphics.DrawImage(
                preview,
                rect);

            preview.Dispose();
        }
    }

    using (var brush =
           new SolidBrush(
               e.ForeColor))
    {
        e.Graphics.DrawString(
            label,
            e.Font,
            brush,
            e.Bounds.Right - 52,
            e.Bounds.Y + 7);
    }

    e.DrawFocusRectangle();
}

