private void CanvasTextEditorSelectionChanged(
    object sender,
    EventArgs e)
{
    /*
     * Sempre que o usuario seleciona ou move um elemento,
     * sincronizamos o editor visual.
     */

    LoadSelectedElementIntoTextEditor();
}
private void DetectHtmlFont()
{
    if (_textEditor == null ||
        _textFontCombo == null)
        return;

    string text =
        _textEditor.Text ?? string.Empty;

    var match =
        System.Text.RegularExpressions.Regex.Match(
            text,
            @"(?:face|font)\s*=\s*[""']?(\d+)");

    if (match.Success &&
        int.TryParse(
            match.Groups[1].Value,
            out int fontId))
    {
        if (fontId >= 0 &&
            fontId < _textFontCombo.Items.Count)
        {
            _textFontCombo.SelectedIndex =
                fontId;
        }
    }
}

private void UpdateTextEditorHtmlFont()
{
    if (_textEditor == null ||
        _textFontCombo == null)
        return;

    if (_canvas.SelectedElement == null)
        return;

    int fontId =
        Math.Max(
            0,
            _textFontCombo.SelectedIndex);

    string html =
        _textEditor.Text ?? string.Empty;

    /*
     * IMPORTANTE:
     *
     * Este metodo NAO deve criar automaticamente
     * uma tag <font>.
     *
     * Antes:
     *
     *     teste
     *
     * virava:
     *
     *     <font face="4">teste</font>
     *
     * Isso acontecia sempre que o ComboBox de fonte
     * era alterado.
     *
     * Agora:
     *
     *     teste
     *
     * permanece:
     *
     *     teste
     *
     * Somente uma tag <font face="N"> que ja exista
     * sera modificada.
     */

    var pattern =
        @"<font\s+face\s*=\s*[""']?\d+[""']?\s*>";

    if (!System.Text.RegularExpressions.Regex.IsMatch(
            html,
            pattern,
            System.Text.RegularExpressions.RegexOptions.IgnoreCase))
    {
        /*
         * Nao existe <font face>.
         *
         * Nao modificar o HTML do usuario.
         */
        return;
    }

    string newHtml =
        System.Text.RegularExpressions.Regex.Replace(
            html,
            pattern,
            "<font face=\"" +
            fontId +
            "\">",
            System.Text.RegularExpressions.RegexOptions.IgnoreCase);

    if (string.Equals(
            html,
            newHtml,
            StringComparison.Ordinal))
    {
        return;
    }

    int caret =
        Math.Min(
            _textEditor.SelectionStart,
            newHtml.Length);

    _textEditor.Text =
        newHtml;

    _textEditor.SelectionStart =
        caret;
}

private void ApplyFormattingToHtml()
{
    if (_textEditor == null)
        return;

    if (_textAlignCombo == null)
        return;

    string html =
        _textEditor.Text ?? string.Empty;

    string open = string.Empty;
    string close = string.Empty;

    switch (_textAlignCombo.SelectedIndex)
    {
        case 1:
            open = "<center>";
            close = "</center>";
            break;

        case 2:
            open = "<div align=\"right\">";
            close = "</div>";
            break;

        case 3:
            open = "<div align=\"justify\">";
            close = "</div>";
            break;
    }

    if (!string.IsNullOrEmpty(open))
    {
        html =
            open +
            html +
            close;
    }

    _textEditor.Text = html;
}

private void WrapSelection(
    string openTag,
    string closeTag)
{
    if (_textEditor == null)
        return;

    int start =
        _textEditor.SelectionStart;

    int length =
        _textEditor.SelectionLength;

    string selected =
        length > 0
            ? _textEditor.SelectedText
            : "texto";

    string replacement =
        openTag +
        selected +
        closeTag;

    _textEditor.SelectedText =
        replacement;

    _textEditor.SelectionStart =
        start +
        replacement.Length;

    ApplyTextEditor(null, EventArgs.Empty);
}

private void ApplyTextEditor(
    object sender,
    EventArgs e)
{
            // GUMPEDITOR_UNDO_BEFORE_ApplyTextEditor
            SaveUndoSnapshot();

    if (_canvas.SelectedElement == null ||
        _textEditor == null)
        return;

    GumpElement element =
        _canvas.SelectedElement;

    if (element.Type !=
            GumpElementType.Html &&
        element.Type !=
            GumpElementType.Label &&
        element.Type !=
            GumpElementType.LabelCropped)
    {
        return;
    }

    string text =
        _textEditor.Text ?? string.Empty;

    element.Text = text;

    if (element.Type ==
        GumpElementType.Html)
    {
        SetElementParameter(
            element,
            4,
            text);
    }
    else if (element.Type ==
        GumpElementType.Label)
    {
        SetElementParameter(
            element,
            3,
            text);
    }
    else if (element.Type ==
        GumpElementType.LabelCropped)
    {
        SetElementParameter(
            element,
            5,
            text);
    }

    if (_canvas.Document != null)
        _canvas.Document.IsModified = true;

    _canvas.RefreshCanvas();
}

private void SetElementParameter(
    GumpElement element,
    int index,
    string value)
{
    while (element.Parameters.Count <= index)
        element.Parameters.Add(string.Empty);

    element.Parameters[index] =
        value;
}
