        // ========================================================

        private void AutoSizeSelectedElement()
        {
            if (_canvas == null ||
                _canvas.SelectedElement == null)
                return;

            GumpElement element =
                _canvas.SelectedElement;

            // ----------------------------------------------------
            // ARTE REAL DO GUMP
            // ----------------------------------------------------

            if (_gumpArtReader != null &&
                element.ArtId > 0)
            {
                try
                {
                    Bitmap bitmap =
                        _gumpArtReader.GetGump(
                            element.ArtId);

                    if (bitmap != null)
                    {
                        bool isArt =
                            element.Type ==
                                GumpElementType.Image ||
                            element.Type ==
                                GumpElementType.Button ||
                            element.Type ==
                                GumpElementType.Checkbox ||
                            element.Type ==
                                GumpElementType.Radio ||
                            element.Type ==
                                GumpElementType.Item;

                        if (isArt)
                        {
                            element.Width =
                                bitmap.Width;

                            element.Height =
                                bitmap.Height;
                        }
                    }
                }
                catch
                {
                }
            }

            // ----------------------------------------------------
            // TEXTO REAL DO FONTS.MUL
            // ----------------------------------------------------

            bool isText =
                element.Type ==
                    GumpElementType.Label ||
                element.Type ==
                    GumpElementType.LabelCropped ||
                element.Type ==
                    GumpElementType.Html;

            if (isText &&
                _uoFontReader != null &&
                _uoFontReader.Fonts != null)
            {
                try
                {
                    int fontId =
                        element.Font;

                    if (fontId < 0 ||
                        fontId >= _uoFontReader.Fonts.Count)
                    {
                        fontId = 0;
                    }

                    string text =
                        element.Text ??
                        string.Empty;

                    if (element.Type ==
                        GumpElementType.Html)
                    {
                        text =
                            System.Text.RegularExpressions.Regex.Replace(
                                text,
                                "<[^>]*>",
                                string.Empty);

                        text =
                            System.Net.WebUtility.HtmlDecode(
                                text);
                    }

                    string[] lines =
                        text.Replace(
                                "\r\n",
                                "\n")
                            .Replace(
                                "\r",
                                "\n")
                            .Split(
                                new[] { '\n' });

                    int maxWidth = 1;
                    int totalHeight = 0;

                    foreach (string line in lines)
                    {
                        using (Bitmap bitmap =
                               _uoFontReader.RenderText(
                                   fontId,
                                   string.IsNullOrEmpty(line)
                                       ? " "
                                       : line,
                                   Color.White,
                                   1.0f))
                        {
                            if (bitmap != null)
                            {
                                maxWidth =
                                    Math.Max(
                                        maxWidth,
                                        bitmap.Width);

                                totalHeight +=
                                    bitmap.Height;
                            }
                        }
                    }

                    element.Width =
                        Math.Max(
                            1,
                            maxWidth);

                    element.Height =
                        Math.Max(
                            1,
                            totalHeight);
                }
                catch
                {
                }
            }

