        private void InitializeHues()
        {
            var path =
                @"C:\Ultima Online Classic\hues.mul";

            if (!File.Exists(path))
                return;

            try
            {
                _hueReader = new HueReader(path);
                _canvas.HueReader = _hueReader;

                PopulateHueList();
            }
            catch (Exception ex)
            {
