        private void PopulatePages()
        {
            _updatingPage = true;

            try
            {
                _pageCombo.Items.Clear();

                if (_canvas.Document == null)
                    return;

                foreach (var page in
                         _canvas.Document.GetPages())
                {
                    _pageCombo.Items.Add(
                        "PÃ¡gina " + page);
                }

                int index = 0;

                foreach (var page in
                         _canvas.Document.GetPages())
                {
                    if (page ==
                        _canvas.Document.CurrentPage)
                    {
                        _pageCombo.SelectedIndex = index;
                        break;
                    }

                    index++;
                }

                if (_pageCombo.SelectedIndex < 0 &&
                    _pageCombo.Items.Count > 0)
                {
                    _pageCombo.SelectedIndex = 0;
                }
            }
            finally
            {
                _updatingPage = false;
            }
        }
        private void PopulateElements()
        {
            _updatingElementsList = true;

            try
            {
                _elementsList.Items.Clear();

                if (_canvas.Document == null)
                    return;

                foreach (var element in
                         _canvas.Document.GetElementsForPage(
                             _canvas.Document.CurrentPage))
                {
                    _elementsList.Items.Add(element);
                }

                SelectElementInList(
                    _canvas.SelectedElement);
            }
            finally
            {
                _updatingElementsList = false;
            }
        
            RefreshGumpZOrderList();}

        private void ElementListSelected(
            object sender,
            EventArgs e)
        {
            if (_updatingElementsList)
                return;

            var element =
                _elementsList.SelectedItem
                as GumpElement;

            if (element == null)
                return;

            _canvas.SelectElement(element);
            UpdateProperties();
        }

        private void SelectElementInList(
            GumpElement element)
        {
            if (element == null)
                return;

            for (int i = 0;
                 i < _elementsList.Items.Count;
                 i++)
            {
                var item =
                    _elementsList.Items[i]
                    as GumpElement;

                if (ReferenceEquals(item, element))
                {
                    _elementsList.SelectedIndex = i;
                    _elementsList.TopIndex =
                        Math.Max(0, i - 3);
                    break;
                }
            }
        }

        private void PageChanged(
            object sender,
            EventArgs e)
        {
            if (_updatingPage)
                return;

            if (_canvas.Document == null)
                return;

            if (_pageCombo.SelectedIndex < 0)
                return;

            int page =
                _pageCombo.SelectedIndex;

            int index = 0;

            foreach (var p in
                     _canvas.Document.GetPages())
            {
                if (index == page)
                {
                    _canvas.Document.CurrentPage = p;
                    _canvas.ClearSelection();
                    PopulateElements();
                    UpdateProperties();
                    _canvas.Invalidate();
                    return;
                }

                index++;
            }
        }

        private void SaveFile(
            object sender,
            EventArgs e)
        {
            if (_canvas.Document == null)
                return;

            string path =
                _canvas.Document.FilePath;

            if (string.IsNullOrWhiteSpace(path))
            {
                SaveAsFile(sender, e);
                return;
            }

            SaveToPath(path);
        }

        private void SaveAsFile(
            object sender,
            EventArgs e)
        {
            if (_canvas.Document == null)
                return;

            using (var dialog =
                   new SaveFileDialog())
            {
                dialog.Title =
                    "Salvar Gump C#";

                dialog.Filter =
                    "Arquivos C# (*.cs)|*.cs";

                dialog.FileName =
                    Path.GetFileName(
                        _canvas.Document.FilePath);

                if (dialog.ShowDialog(this) !=
                    DialogResult.OK)
                    return;

                SaveToPath(dialog.FileName);
            }
        }

        private void SaveToPath(string path)
        {
            try
            {
                var document =
                    _canvas.Document;

                string source =
                    GumpCodeExporter.Export(
                        document);

                File.WriteAllText(
                    path,
                    source);

                document.SourceCode =
                    source;

                document.FilePath =
                    path;

                document.IsModified =
                    false;

                Text =
                    "UOGumpDesigner - " +
                    Path.GetFileName(path);

                UpdateStatus();

                MessageBox.Show(
                    this,
                    "Gump salvo com sucesso.\r\n\r\n" +
                    path,
                    "Gump Editor",
                    MessageBoxButtons.OK,
                    MessageBoxIcon.Information);
            }
            catch (Exception ex)
            {
                MessageBox.Show(
                    this,
                    "Erro ao salvar o Gump.\r\n\r\n" +
                    ex.Message,
                    "Erro",
                    MessageBoxButtons.OK,
                    MessageBoxIcon.Error);
            }
        }

        private void AddElement(
            object sender,
            EventArgs e)
        {
            if (_canvas.Document == null)
            {
                MessageBox.Show(
                    this,
                    "Abra um Gump primeiro.",
                    "Gump Editor",
                    MessageBoxButtons.OK,
                    MessageBoxIcon.Information);

                return;
            }

            using (var dialog =
                   new AddElementDialog())
            {
                if (dialog.ShowDialog(this) !=
                    DialogResult.OK)
                    return;

                var element =
                    dialog.Element;

                element.Page =
                    _canvas.Document.CurrentPage;

                _canvas.Document.AddElement(
                    element);

                PopulateElements();
                UpdateStatus();

                _canvas.Invalidate();

                _canvas.SelectElement(
                    element);
            }
        }

