             * estiver digitando em um campo de texto.
             */
            Control focused =
                FindFocusedControl(this);

            bool textControl =
                focused is TextBoxBase ||
                focused is ComboBox;

            if (textControl)
            {
                return base.ProcessCmdKey(
                    ref msg,
                    keyData);
            }

            if (keyData == (Keys.Control | Keys.C))
            {
                if (_canvas != null &&
                    _canvas.CopySelectedElement())
                {
                    UpdateStatus();
                    return true;
                }
            }

            if (keyData == (Keys.Control | Keys.X))
            {
                if (_canvas != null &&
                    _canvas.CutSelectedElement())
                {
                    PopulateElements();
                    UpdateProperties();
                    UpdateStatus();
                    return true;
                }
            }

            if (keyData == (Keys.Control | Keys.V))
            {
                if (_canvas != null &&
                    _canvas.PasteElement())
                {
                    PopulateElements();
                    UpdateProperties();
                    UpdateStatus();
                    return true;
                }
            }

            if (keyData == Keys.Delete)
            {
                DeleteElement(
                    null,
                    EventArgs.Empty);

                return true;
