        private static Control FindFocusedControl(
            Control root)
        {
            if (root == null)
                return null;

            Control current = root;

            while (current is ContainerControl)
            {
                ContainerControl container =
                    current as ContainerControl;

                Control child =
                    container.ActiveControl;

                if (child == null)
                    break;

                current = child;
            }

            return current;
