        private void DeleteElement(
            object sender,
            EventArgs e)
        {
            // GUMPEDITOR_UNDO_BEFORE_DeleteElement
            SaveUndoSnapshot();

            var element =
                _canvas.SelectedElement;

            if (element == null)
                return;

            if (MessageBox.Show(
                    this,
                    "Excluir o elemento selecionado?",
                    "Gump Editor",
                    MessageBoxButtons.YesNo,
                    MessageBoxIcon.Question) !=
                DialogResult.Yes)
                return;

            _canvas.Document.RemoveElement(
                element);

            _canvas.ClearSelection();

            PopulateElements();
            UpdateProperties();
            UpdateStatus();

            _canvas.Invalidate();
        }


