                    "Gump Editor",
                    MessageBoxButtons.OK,
                    MessageBoxIcon.Warning);

                return;
            }

            int artId =
                (int)_artBrowserId.Value;

            int hue =
                (int)_artBrowserHue.Value;

            try
            {
                var image =
                    _gumpArtReader.GetGump(
                        artId);

                if (image == null)
                {
                    _artPreview.Image = null;
                    return;
                }

                if (_hueReader != null &&
                    hue > 0)
                {
                    image =
                        _hueReader.ApplyHue(
                            image,
                            hue);
                }

                var old =
                    _artPreview.Image;

                _artPreview.Image =
                    image;

                if (old != null)
                    old.Dispose();
            }
            catch (Exception ex)
            {
                MessageBox.Show(
                    this,
                    "Erro ao visualizar a arte.\r\n\r\n" +
                    ex.Message,
                    "Gump Editor",
                    MessageBoxButtons.OK,
                    MessageBoxIcon.Error);
            }
        }

        private void AddArtFromBrowser(
            object sender,
            EventArgs e)
        {
            if (_canvas.Document == null)
                return;

            var element = new GumpElement
            {
                Type = GumpElementType.Image,
                X = 20,
                Y = 20,
                ArtId = (int)_artBrowserId.Value,
                Hue = (int)_artBrowserHue.Value,
                Page =
                    _canvas.Document.CurrentPage
            };

            try
            {
                if (_gumpArtReader != null)
                {
                    var image =
                        _gumpArtReader.GetGump(
                            element.ArtId);

                    if (image != null)
                    {
                        element.Width =
                            image.Width;

                        element.Height =
                            image.Height;
                    }
                }
            }
            catch
            {
                element.Width = 44;
                element.Height = 44;
            }

            _canvas.Document.AddElement(element);

            PopulateElements();

            _canvas.SelectElement(element);

            UpdateProperties();
            UpdateStatus();

            _canvas.Invalidate();
        }

        private void PopulateHueList()
        {
            if (_hueList == null ||
                _hueReader == null)
                return;

            _hueList.Items.Clear();

            foreach (var hue in _hueReader.Hues)
            {
                _hueList.Items.Add(hue);
            }
        }

        private void DrawHueItem(
            object sender,
            DrawItemEventArgs e)
        {
            if (e.Index < 0 ||
                _hueReader == null)
                return;

            var hue =
                _hueList.Items[e.Index]
                as HueData;

            if (hue == null)
                return;

            e.DrawBackground();

            using (var brush =
                   new SolidBrush(
                       GetHueColor(hue)))
            {
                var rect =
                    new Rectangle(
                        e.Bounds.X + 4,
                        e.Bounds.Y + 4,
                        40,
                        e.Bounds.Height - 8);

                e.Graphics.FillRectangle(
                    brush,
                    rect);
            }

            using (var brush =
                   new SolidBrush(e.ForeColor))
            {
                string text =
                    hue.Id +
                    " - " +
                    hue.Name;

                e.Graphics.DrawString(
                    text,
                    Font,
                    brush,
                    e.Bounds.X + 52,
                    e.Bounds.Y + 5);
            }

            e.DrawFocusRectangle();
        }

        private Color GetHueColor(
            HueData hue)
        {
            if (hue == null ||
                hue.Colors == null ||
                hue.Colors.Length == 0)
                return Color.Gray;

            return hue.Colors[
                hue.Colors.Length / 2];
        }

        private static uint HueColorToRgb(
            ushort c)
        {
            byte[] table =
            {
                0x00, 0x08, 0x10, 0x18,
                0x20, 0x29, 0x31, 0x39,
                0x41, 0x4A, 0x52, 0x5A,
                0x62, 0x6A, 0x73, 0x7B,
                0x83, 0x8B, 0x94, 0x9C,
                0xA4, 0xAC, 0xB4, 0xBD,
                0xC5, 0xCD, 0xD5, 0xDE,
                0xE6, 0xEE, 0xF6, 0xFF
            };

            return (uint)(
                table[(c >> 10) & 0x1F] |
                (table[(c >> 5) & 0x1F] << 8) |
                (table[c & 0x1F] << 16));
        }

        private void HueSelected(
            object sender,
            EventArgs e)
        {
            if (_hueList.SelectedItem == null)
                return;

            var hue =
                _hueList.SelectedItem as HueData;

            if (hue == null)
                return;

            _huePreview.BackColor =
                GetHueColor(hue);
        }

        private void UseSelectedHue(
            object sender,
            EventArgs e)
        {
            if (_hueList.SelectedItem == null)
                return;

            var hue =
                _hueList.SelectedItem as HueData;

            if (hue == null)
                return;

            _hue.Value =
                Math.Max(
                    _hue.Minimum,
                    Math.Min(
                        _hue.Maximum,
                        hue.Id));

            _artBrowserHue.Value =
                Math.Max(
                    _artBrowserHue.Minimum,
                    Math.Min(
                        _artBrowserHue.Maximum,
                        hue.Id));

            PreviewArt(
                sender,
                e);
        }

        private void UpdateStatus()
        {
            if (_canvas.Document == null)
                return;

            var document =
                _canvas.Document;

            _statusStrip.Items.Clear();

            string modified =
                document.IsModified
                    ? " *"
                    : string.Empty;

            string selected =
                _canvas.SelectedElement == null
                    ? "Nenhum elemento selecionado"
                    : _canvas.SelectedElement.Type.ToString();

            _statusStrip.Items.Add(
                new ToolStripStatusLabel(
                    document.Name +
                    modified +
                    " | " +
                    document.Width +
                    "x" +
                    document.Height +
                    " | " +
                    document.Elements.Count +
                    " elementos" +
                    " | " +
                    selected));
        }

        private void ZoomChanged(
            object sender,
            EventArgs e)
        {
            if (_zoomCombo.SelectedItem == null)
                return;

            string text =
                _zoomCombo.SelectedItem.ToString();

            text =
                text.Replace(
                    "%",
                    string.Empty);

            float percentage;

            if (!float.TryParse(
                    text,
                    out percentage))
                return;

            _canvas.Zoom =
                percentage / 100f;

            _canvas.Invalidate();
        }

        private void ToggleGrid(
            object sender,
            EventArgs e)
        {
            var item =
                sender as ToolStripMenuItem;

            if (item == null)
                return;

            item.Checked =
                !item.Checked;

            _gridButton.Checked =
                item.Checked;

            _canvas.ShowGrid =
                item.Checked;

            _canvas.Invalidate();
        }

