        private void GumpFontComboDrawItem(
    object sender,
    DrawItemEventArgs e)
{
    if (e.Index < 0)
        return;

    e.DrawBackground();

    int fontId = e.Index - 1;

    if (_uoFontReader != null &&
        fontId >= 0 &&
        fontId < _uoFontReader.Fonts.Count)
    {
        try
        {
            Bitmap preview =
                _uoFontReader.RenderText(
                    fontId,
                    "AaBbCc 0123456789",
                    Color.White,
                    1.0f);

            if (preview != null)
            {
                int maxWidth =
                    Math.Max(
                        1,
                        e.Bounds.Width - 70);

                int maxHeight =
                    Math.Max(
                        1,
                        e.Bounds.Height - 4);

                float scale = 1.0f;

                if (preview.Width > maxWidth)
                    scale =
                        Math.Min(
                            scale,
                            (float)maxWidth /
                            preview.Width);

                if (preview.Height > maxHeight)
                    scale =
                        Math.Min(
                            scale,
                            (float)maxHeight /
                            preview.Height);

                int width =
                    Math.Max(
                        1,
                        (int)(preview.Width * scale));

                int height =
                    Math.Max(
                        1,
                        (int)(preview.Height * scale));

                Rectangle rect =
                    new Rectangle(
                        e.Bounds.X + 4,
                        e.Bounds.Y +
                            ((e.Bounds.Height -
                              height) / 2),
                        width,
                        height);

                e.Graphics.DrawImage(
                    preview,
                    rect);

                preview.Dispose();
            }
        }
        catch
        {
        }
    }

    using (var brush =
           new SolidBrush(
               e.ForeColor))
    {
        string fontName =
    fontId < 0
        ? "PADRAO DO CLIENTE"
        : "Font " + fontId;

e.Graphics.DrawString(
            fontName,
            e.Font,
            brush,
            e.Bounds.Right - 58,
            e.Bounds.Y + 8);
    }

    e.DrawFocusRectangle();
}

