private void LoadSelectedElementIntoTextEditor()
{
    if (_canvas == null ||
        _gumpTextEditorPanel == null)
    {
        return;
    }

    GumpElement element =
        _canvas.SelectedElement;

    if (element == null)
    {
        _gumpTextEditorPanel.Visible = false;

        if (_gumpHtmlGroup != null)
            _gumpHtmlGroup.Visible = false;

        return;
    }

    string typeName =
        element.GetType().Name;

    bool isHtml =
        element.Type == GumpElementType.Html ||
        typeName.IndexOf(
            "Html",
            StringComparison.OrdinalIgnoreCase) >= 0;

    bool isText =
        typeName.IndexOf(
            "Label",
            StringComparison.OrdinalIgnoreCase) >= 0
        ||
        typeName.IndexOf(
            "Text",
            StringComparison.OrdinalIgnoreCase) >= 0
        ||
        isHtml;

        if (isHtml)
    {
                // GUMPEDITOR_HTML_VISIBILITY_V95

                if (_propertiesTabs != null &&
                    _gumpHtmlTab != null)
                {
                    _propertiesTabs.SelectedTab =
                        _gumpHtmlTab;
                }

                if (_textEditorGroup != null)
                    _textEditorGroup.Visible = true;

                if (_gumpTextEditorPanel != null)
                    _gumpTextEditorPanel.Visible = true;

                if (_gumpHtmlGroup != null)
                    _gumpHtmlGroup.Visible = true;

        _gumpTextEditorPanel.Visible =
            false;

        if (_gumpHtmlGroup != null)
            _gumpHtmlGroup.Visible =
                true;

        if (_propertiesTabs != null &&
            _gumpHtmlTab != null)
        {
            _propertiesTabs.SelectedTab =
                _gumpHtmlTab;
        }

        if (_gumpHtmlEditor != null)
        {
            string html =
                element.Text ??
                string.Empty;

            if (element.Parameters.Count > 4)
            {
                html =
                    element.Parameters[4] ??
                    html;
            }

            _gumpHtmlEditor.Text =
                html;
        }

        return;
    }

    _gumpTextEditorPanel.Visible =
        isText;

    if (!isText)
        return;

    // ========================================================
    // TEXTO NORMAL
    // ========================================================

    if (_gumpTextEditor != null)
    {
        _gumpTextEditor.Text =
            element.Text ?? string.Empty;
    }

    // ========================================================
    // HTML LITERAL
    //
    // Prioridade:
    // Parameters[4]
    // caso exista.
    // ========================================================

    if (isHtml &&
        _gumpHtmlEditor != null)
    {
        string html =
            element.Text ?? string.Empty;

        if (element.Parameters.Count > 4)
        {
            html =
                element.Parameters[4] ?? html;
        }

        _gumpHtmlEditor.Text =
            html;
    }

    // ========================================================
    // FONTE UO
    // ========================================================

    int fontId =
        element.Font;

    if (_uoFontReader == null ||
        fontId < -1 ||
        fontId >= _uoFontReader.Fonts.Count)
    {
        fontId = -1;
    }

    if (_gumpFontCombo != null)
    {
        int comboIndex =
            fontId + 1;

        if (comboIndex >= 0 &&
            comboIndex < _gumpFontCombo.Items.Count)
        {
            _gumpFontCombo.SelectedIndex =
                comboIndex;
        }
    }

    _selectedUoFont =
        fontId;

    if (_gumpFontInfo != null)
    {
        _gumpFontInfo.Text =
            "Fonte UO " + fontId;
    }

    // ========================================================
    // TAMANHO
    // ========================================================

    if (_gumpSizeCombo != null)
    {
        string size =
            element.TextSize > 0
                ? element.TextSize.ToString()
                : "12";

        if (_gumpSizeCombo.Items.Contains(size))
        {
            _gumpSizeCombo.SelectedItem =
                size;
        }
    }

    // ========================================================
    // ALINHAMENTO
    // ========================================================

    if (_gumpAlignCombo != null)
    {
        int align =
            element.TextAlign;

        if (align < 0 ||
            align >= _gumpAlignCombo.Items.Count)
        {
            align = 0;
        }

        _gumpAlignCombo.SelectedIndex =
            align;
    }

    // ========================================================
    // BOLD
    // ========================================================

    if (_gumpBoldButton != null)
    {
        _gumpBoldButton.Tag =
            element.Bold;

        _gumpBoldButton.BackColor =
            element.Bold
                ? SystemColors.Highlight
                : SystemColors.Control;
    }

    // ========================================================
    // ITALIC
    // ========================================================

    if (_gumpItalicButton != null)
    {
        _gumpItalicButton.Tag =
            element.Italic;

        _gumpItalicButton.BackColor =
            element.Italic
                ? SystemColors.Highlight
                : SystemColors.Control;
    }

    // ========================================================
    // UNDERLINE
    // ========================================================

    if (_gumpUnderlineButton != null)
    {
        _gumpUnderlineButton.Tag =
            element.Underline;

        _gumpUnderlineButton.BackColor =
            element.Underline
                ? SystemColors.Highlight
                : SystemColors.Control;
    }

    // ========================================================
    // HUE
    // ========================================================

    if (_gumpHueNumeric != null)
    {
        decimal hue =
            element.Hue;

        if (hue < _gumpHueNumeric.Minimum)
            hue = _gumpHueNumeric.Minimum;

        if (hue > _gumpHueNumeric.Maximum)
            hue = _gumpHueNumeric.Maximum;

        _gumpHueNumeric.Value =
            hue;
    }

    if (_canvas != null)
        _canvas.Invalidate();
}


