        // APLICA AS ALTERACOES AO ELEMENTO
        // ====================================================

        private void ApplyVisualTextEditor()
{
    if (_canvas == null ||
        _canvas.SelectedElement == null)
    {
        return;
    }

    GumpElement element =
        _canvas.SelectedElement;

    SaveUndoSnapshot();

    string typeName =
        element.GetType().Name;

    bool isHtml =
        element.Type == GumpElementType.Html ||
        typeName.IndexOf(
            "Html",
            StringComparison.OrdinalIgnoreCase) >= 0;

    // ========================================================
    // TEXTO
    // ========================================================

    if (_gumpTextEditor != null)
    {
        element.Text =
            _gumpTextEditor.Text ??
            string.Empty;
    }

    // ========================================================
    // HTML LITERAL
    //
    // NAO usar Trim().
    // NAO inserir tags.
    // NAO alterar o conteudo.
    // ========================================================

    if (isHtml &&
        _gumpHtmlEditor != null)
    {
        string html =
            _gumpHtmlEditor.Text ??
            string.Empty;

        element.Text =
            html;

        while (element.Parameters.Count <= 4)
        {
            element.Parameters.Add(
                string.Empty);
        }

        element.Parameters[4] =
            html;
    }

    // ========================================================
    // FONTE UO
    // ========================================================

    int fontId = -1;

    if (_gumpFontCombo != null &&
        _gumpFontCombo.SelectedIndex >= 0)
    {
        fontId =
            _gumpFontCombo.SelectedIndex - 1;
    }

    if (_uoFontReader != null)
    {
        if (fontId < -1 ||
            fontId >= _uoFontReader.Fonts.Count)
        {
            fontId = -1;
        }
    }

    element.Font =
        fontId;

    // ========================================================
    // TAMANHO
    // ========================================================

    int size = 12;

    if (_gumpSizeCombo != null &&
        _gumpSizeCombo.SelectedItem != null)
    {
        int parsedSize;

        if (int.TryParse(
            _gumpSizeCombo.SelectedItem.ToString(),
            out parsedSize))
        {
            size = parsedSize;
        }

        if (size <= 0)
            size = 12;
    }

    element.TextSize =
        size;

    // ========================================================
    // ALINHAMENTO
    // ========================================================

    if (_gumpAlignCombo != null &&
        _gumpAlignCombo.SelectedIndex >= 0)
    {
        element.TextAlign =
            _gumpAlignCombo.SelectedIndex;
    }

    // ========================================================
    // BOLD
    // ========================================================

    if (_gumpBoldButton != null)
    {
        element.Bold =
            Convert.ToBoolean(
                _gumpBoldButton.Tag ?? false);
    }

    // ========================================================
    // ITALIC
    // ========================================================

    if (_gumpItalicButton != null)
    {
        element.Italic =
            Convert.ToBoolean(
                _gumpItalicButton.Tag ?? false);
    }

    // ========================================================
    // UNDERLINE
    // ========================================================

    if (_gumpUnderlineButton != null)
    {
        element.Underline =
            Convert.ToBoolean(
                _gumpUnderlineButton.Tag ?? false);
    }

    // ========================================================
    // HUE
    // ========================================================

    if (_gumpHueNumeric != null)
    {
        element.Hue =
            (int)_gumpHueNumeric.Value;
    }

    if (_canvas.Document != null)
    {
        _canvas.Document.IsModified = true;
    }

    _canvas.Invalidate();

    LoadSelectedElementIntoTextEditor();
}
