        private void HtmlWrapSelection(
            string openTag,
            string closeTag)
        {
            if (_gumpHtmlEditor == null)
                return;

            int start =
                _gumpHtmlEditor.SelectionStart;

            int length =
                _gumpHtmlEditor.SelectionLength;

            string selected =
                length > 0
                    ? _gumpHtmlEditor.SelectedText
                    : "texto";

            string replacement =
                openTag +
                selected +
                closeTag;

            _gumpHtmlEditor.SelectedText =
                replacement;

            if (length <= 0)
            {
                _gumpHtmlEditor.SelectionStart =
                    start +
                    openTag.Length;

                _gumpHtmlEditor.SelectionLength =
                    selected.Length;
            }
            else
            {
                _gumpHtmlEditor.SelectionStart =
                    start +
                    replacement.Length;
            }

            _gumpHtmlEditor.Focus();
        }

        private void HtmlInsertText(
            string value)
        {
            if (_gumpHtmlEditor == null)
                return;

            int start =
                _gumpHtmlEditor.SelectionStart;

            _gumpHtmlEditor.SelectedText =
                value;

            _gumpHtmlEditor.SelectionStart =
                start +
                value.Length;

            _gumpHtmlEditor.Focus();
        }

        private void HtmlRemoveFormattingFromSelection()
        {
            if (_gumpHtmlEditor == null)
                return;

            int start =
                _gumpHtmlEditor.SelectionStart;

            int length =
                _gumpHtmlEditor.SelectionLength;

            if (length <= 0)
                return;

            string selected =
                _gumpHtmlEditor.SelectedText;

            string plain =
                System.Text.RegularExpressions.Regex.Replace(
                    selected,
                    @"<[^>]+>",
                    string.Empty);

            _gumpHtmlEditor.SelectedText =
                plain;

            _gumpHtmlEditor.SelectionStart =
                start +
                plain.Length;

            _gumpHtmlEditor.Focus();
        }
        private void ApplyGumpHtmlEditor()
        {
            if (_canvas == null ||
                _canvas.SelectedElement == null ||
                _gumpHtmlEditor == null)
            {
                return;
            }

            GumpElement element =
                _canvas.SelectedElement;

            if (element.Type !=
                GumpElementType.Html)
            {
                MessageBox.Show(
                    this,
                    "Selecione um elemento HTML.",
                    "Editor HTML",
                    MessageBoxButtons.OK,
                    MessageBoxIcon.Information);

                return;
            }

            string html =
                _gumpHtmlEditor.Text ??
                string.Empty;

            SaveUndoSnapshot();

            element.Text =
                html;

            while (element.Parameters.Count <= 4)
            {
                element.Parameters.Add(
                    string.Empty);
            }

            element.Parameters[4] =
                html;

            if (_canvas.Document != null)
            {
                _canvas.Document.IsModified =
                    true;
            }

            _canvas.Invalidate();

            PopulateElements();
            UpdateProperties();
            UpdateStatus();
        }
        private void MoveSelectedGumpZOrder(
            int mode)
        {
            if (_canvas == null ||
                _canvas.SelectedElement == null ||
                _canvas.Document == null)
            {
                return;
            }

            GumpElement selected =
                _canvas.SelectedElement;

            List<GumpElement> pageElements =
                new List<GumpElement>();

            List<int> indexes =
                new List<int>();

            List<GumpElement> allElements =
                _canvas.Document.Elements;

            for (
                int i = 0;
                i < allElements.Count;
                i++)
            {
                GumpElement element =
                    allElements[i];

                if (element != null &&
                    element.Page ==
                    selected.Page)
                {
                    indexes.Add(i);
                    pageElements.Add(element);
                }
            }

            int current =
                pageElements.IndexOf(selected);

            if (current < 0)
                return;

            int target =
                current;

            if (mode == 0)
            {
                target = 0;
            }
            else if (mode == 1)
            {
                target =
                    Math.Max(
                        0,
                        current - 1);
            }
            else if (mode == 2)
            {
                target =
                    Math.Min(
                        pageElements.Count - 1,
                        current + 1);
            }
            else if (mode == 3)
            {
                target =
                    pageElements.Count - 1;
            }
            else
            {
                return;
            }

            MoveSelectedGumpZOrderTo(
                target + 1);
        }
        private void MoveSelectedGumpZOrderTo(
            int requestedPosition)
        {
            if (_canvas == null ||
                _canvas.SelectedElement == null ||
                _canvas.Document == null)
            {
                return;
            }

            GumpElement selected =
                _canvas.SelectedElement;

            List<GumpElement> pageElements =
                new List<GumpElement>();

            List<int> indexes =
                new List<int>();

            List<GumpElement> allElements =
                _canvas.Document.Elements;

            for (
                int i = 0;
                i < allElements.Count;
                i++)
            {
                GumpElement element =
                    allElements[i];

                if (element != null &&
                    element.Page ==
                    selected.Page)
                {
                    indexes.Add(i);
                    pageElements.Add(element);
                }
            }

            int count =
                pageElements.Count;

            if (count <= 0)
                return;

            int current =
                pageElements.IndexOf(selected);

            if (current < 0)
                return;

            int target =
                Math.Max(
                    1,
                    Math.Min(
                        count,
                        requestedPosition))
                - 1;

            if (target == current)
            {
                RefreshGumpZOrderList();

                SelectElementInZOrderList(
                    selected);

                return;
            }

            SaveUndoSnapshot();

            pageElements.RemoveAt(
                current);

            pageElements.Insert(
                target,
                selected);

            for (
                int i = 0;
                i < indexes.Count;
                i++)
            {
                allElements[indexes[i]] =
                    pageElements[i];
            }

            _canvas.Document.IsModified =
                true;

            _canvas.Invalidate();

            PopulateElements();
            UpdateProperties();
            UpdateStatus();

            RefreshGumpZOrderList();

            SelectElementInZOrderList(
                selected);
        }

        private void GumpZOrderListSelected(
            object sender,
            EventArgs e)
        {
            if (_updatingZOrderList ||
                _gumpZOrderList == null)
            {
                return;
            }

            GumpElement element =
                _gumpZOrderList.SelectedItem
                as GumpElement;

            if (element == null)
                return;

            if (_gumpZOrderPosition != null &&
                _gumpZOrderList.SelectedIndex >= 0)
            {
                int position =
                    _gumpZOrderList.SelectedIndex + 1;

                if (
                    position >=
                    (int)_gumpZOrderPosition.Minimum &&
                    position <=
                    (int)_gumpZOrderPosition.Maximum
                )
                {
                    _gumpZOrderPosition.Value =
                        position;
                }
            }

            // SelectedElement e somente leitura.
            // Nunca atribuir diretamente.
            if (_canvas != null)
            {
                _canvas.SelectElement(
                    element);
            }

            UpdateProperties();
            UpdateStatus();
        }

        private void SelectElementInZOrderList(
            GumpElement element)
        {
            if (_gumpZOrderList == null ||
                element == null)
            {
                return;
            }

            for (
                int i = 0;
                i < _gumpZOrderList.Items.Count;
                i++)
            {
                GumpElement item =
                    _gumpZOrderList.Items[i]
                    as GumpElement;

                if (ReferenceEquals(
                    item,
                    element))
                {
                    _updatingZOrderList =
                        true;

                    try
                    {
                        _gumpZOrderList.SelectedIndex =
                            i;

                        _gumpZOrderList.TopIndex =
                            Math.Max(
                                0,
                                i - 3);

                        if (_gumpZOrderPosition != null)
                        {
                            int position =
                                i + 1;

                            if (
                                position >=
                                (int)_gumpZOrderPosition.Minimum &&
                                position <=
                                (int)_gumpZOrderPosition.Maximum
                            )
                            {
                                _gumpZOrderPosition.Value =
                                    position;
                            }
                        }
                    }
                    finally
                    {
                        _updatingZOrderList =
                            false;
                    }

                    break;
                }
            }
        }

        private void RefreshGumpZOrderList()
        {
            if (_gumpZOrderList == null)
                return;

            _updatingZOrderList =
                true;

            try
            {
                _gumpZOrderList.Items.Clear();

                if (_canvas == null ||
                    _canvas.Document == null)
                {
                    return;
                }

                List<GumpElement> elements =
                    new List<GumpElement>();

                foreach (
                    GumpElement element
                    in _canvas.Document.Elements)
                {
                    if (element != null &&
                        element.Page ==
                        _canvas.Document.CurrentPage)
                    {
                        elements.Add(
                            element);
                    }
                }

                foreach (
                    GumpElement element
                    in elements)
                {
                    _gumpZOrderList.Items.Add(
                        element);
                }

                if (_gumpZOrderPosition != null)
                {
                    _gumpZOrderPosition.Minimum =
                        1;

                    _gumpZOrderPosition.Maximum =
                        Math.Max(
                            1,
                            elements.Count);
                }
            }
            finally
            {
                _updatingZOrderList =
                    false;
            }

            if (_canvas != null)
            {
                SelectElementInZOrderList(
                    _canvas.SelectedElement);
            }
        }

        private void DrawGumpZOrderItem(
            object sender,
            DrawItemEventArgs e)
        {
            if (e.Index < 0 ||
                _gumpZOrderList == null)
            {
                return;
            }

            e.DrawBackground();

            GumpElement element =
                _gumpZOrderList.Items[e.Index]
                as GumpElement;

            if (element == null)
                return;

            string prefix =
                (e.Index + 1).ToString("00");

            string label =
                prefix +
                "  |  " +
                element.Type.ToString();

            if (e.Index == 0)
            {
                label +=
                    "  |  ATRAS";
            }
            else if (
                e.Index ==
                _gumpZOrderList.Items.Count - 1)
            {
                label +=
                    "  |  FRENTE";
            }

            using (
                SolidBrush brush =
                    new SolidBrush(
                        e.ForeColor))
            {
                e.Graphics.DrawString(
                    label,
                    e.Font,
                    brush,
                    e.Bounds.X + 8,
                    e.Bounds.Y + 8);
            }

            e.DrawFocusRectangle();
        }

        private void ApplyGumpZOrderPosition()
        {
            if (_gumpZOrderPosition == null)
                return;

            MoveSelectedGumpZOrderTo(
                (int)_gumpZOrderPosition.Value);
        }
